SELECT t2.store_code, t2.amount, t2.discount
FROM (
    SELECT t1.store_code AS store_code, t1.amount AS amount, t1.discount AS discount
    FROM daily_sales AS t1
    WHERE (t1.sales_date = sqlc.arg(sales_date)::date)
      AND (t1.discount > '0'::numeric)
) AS t2
WHERE (sqlc.narg(cursor_amount)::numeric IS NULL OR (t2.amount, t2.store_code) < (sqlc.narg(cursor_amount)::numeric, sqlc.narg(cursor_store_code)::int4))
ORDER BY t2.amount DESC, t2.store_code DESC
LIMIT sqlc.arg(row_limit)::int4;
